const ROLE_SELECTORS = {
  alert: '[role="alert"]',
  button: 'button, [role="button"]',
  list: 'ul, ol, [role="list"]',
  listitem: 'li, [role="listitem"]',
  status: '[role="status"]',
  textbox: 'input:not([type]), input[type="text"], textarea, [role="textbox"]',
};
function accessibleName(el) {
  if (el.getAttribute('aria-label')) return el.getAttribute('aria-label');
  if (el.labels && el.labels.length) return el.labels[0].textContent.trim();
  return el.textContent.trim();
}
function queryAllByRole(root, role, { name } = {}) {
  return [...root.querySelectorAll(ROLE_SELECTORS[role])]
    .filter((el) => !el.closest('[hidden]'))
    .filter((el) => name === undefined || accessibleName(el) === name);
}
function queryByRole(root, role, options) {
  return queryAllByRole(root, role, options)[0] ?? null;
}
function getAllByRole(root, role, options = {}) {
  const found = queryAllByRole(root, role, options);
  if (!found.length) throw new Error(`Unable to find role "${role}"${options.name ? ` named "${options.name}"` : ''}`);
  return found;
}
function getByRole(root, role, options = {}) {
  const found = getAllByRole(root, role, options);
  if (found.length > 1) throw new Error(`Found ${found.length} elements with role "${role}"`);
  return found[0];
}
function queryByText(root, text) {
  return [...root.querySelectorAll('*')].find((el) =>
    !el.closest('[hidden]') &&
    el.textContent.trim() === text &&
    ![...el.children].some((child) => child.textContent.trim() === text)) ?? null;
}
function getByText(root, text) {
  const el = queryByText(root, text);
  if (!el) throw new Error(`Unable to find text "${text}"`);
  return el;
}
