// ────────────────────────────────────────────────────────────────────────────

let container;

beforeEach(() => {
  container = document.createElement('div');
  document.body.append(container);
});

afterEach(() => {
  container.remove();
});

describe('renderBalances', () => {
  test('renders a list labelled Balances', () => {
    renderBalances(container, { Ana: 1200, Ben: -1200 });

    expect(getByRole(container, 'list', { name: 'Balances' })).toBeTruthy();
  });

  test('says who owes and who is owed, sorted by name', () => {
    renderBalances(container, { Ben: -500, Cai: 0, Ana: 500 });

    const items = getAllByRole(container, 'listitem');
    expect(items.map((item) => item.textContent)).toEqual([
      'Ana is owed $5.00',
      'Ben owes $5.00',
      'Cai is settled up',
    ]);
  });

  test('shows an empty state instead of an empty list', () => {
    renderBalances(container, {});

    expect(getByText(container, 'No expenses yet')).toBeTruthy();
    expect(queryByRole(container, 'list')).toBeNull();
  });
});
